// generated by tools/pack.ts from registry/ and template/: don't edit, run `bun tools/pack.ts`
export const REGISTRY: Record<string, string> = {
  "callout.tsx": "// raea add callout: a short labelled card that slides in with the line it supports (a step, a claim, a stat), in the\n// band away from the face. Put it in a <Sequence from durationInFrames> timed to the words (word(\"phrase\") finds them).\nimport { Easing, Region, interpolate, useCurrentFrame } from \"@raea/motion\";\n\ntype Props = {\n  /** the small line above: \"Step 1\", \"Fact\", \"New\" */\n  label?: string;\n  title: string;\n  detail?: string;\n  region?: \"auto\" | \"top\" | \"bottom\" | \"center\";\n};\n\nexport default function Callout({ label, title, detail, region = \"top\" }: Props) {\n  const f = useCurrentFrame();\n  const t = interpolate(f, [0, 10], [0, 1], { extrapolateRight: \"clamp\", easing: Easing.bezier(0.05, 0.7, 0.1, 1) });\n  return (\n    <Region name={region}>\n      <div style={{ opacity: t, transform: `translateY(${(1 - t) * 40}px)` }} className=\"mx-auto max-w-[86%] rounded-brand bg-brand-surface px-10 py-8 font-brand text-brand-on-surface shadow-xl\">\n        {label ? <div className=\"mb-2 text-label font-bold uppercase tracking-widest text-brand-accent\">{label}</div> : null}\n        <div className=\"text-title font-extrabold leading-tight\">{title}</div>\n        {detail ? <div className=\"mt-2 text-body opacity-80\">{detail}</div> : null}\n      </div>\n    </Region>\n  );\n}\n",
  "captions.tsx": "// raea add captions: the spoken words, a few at a time, the word being said lit. Reads the edit's words itself\n// (useWords(): `raea cut` writes them beside cuts.ts). Sits in the bottom band (parts take the top by default, so they\n// never share one), on the brand's surface with its own text colour, a pair the kit keeps readable on any footage.\n// Styled only from the brand's tokens (brand/brand.css); change anything here, it's yours.\nimport { Region, useCurrentFrame, useWords } from \"@raea/motion\";\n\ntype Props = {\n  /** words on screen at once */\n  per?: number;\n  /** where: \"bottom\" by default (parts default to \"top\"); \"auto\" keeps clear of the face */\n  region?: \"auto\" | \"top\" | \"bottom\" | \"center\";\n};\n\nexport default function Captions({ per = 3, region = \"bottom\" }: Props) {\n  const f = useCurrentFrame();\n  const words = useWords();\n  const i = words.findIndex((w) => f >= w.from && f < w.to);\n  // between words, the last group stays up until the next word starts\n  const at = i >= 0 ? i : words.findLastIndex((w) => w.to <= f);\n  if (at < 0) return null;\n  const start = at - (at % per);\n  const group = words.slice(start, start + per);\n  if (group.length === 0 || f >= group[group.length - 1].to + 6) return null;\n  return (\n    <Region name={region}>\n      <div className=\"flex justify-center\">\n        <div className=\"flex max-w-[90%] flex-wrap justify-center gap-x-[0.28em] rounded-brand bg-brand-surface px-8 py-4 text-center font-brand text-caption font-extrabold leading-tight text-brand-on-surface shadow-xl\">\n          {group.map((w, k) => (\n            <span key={k} className={start + k === i ? \"text-brand-accent\" : \"\"}>{w.text}</span>\n          ))}\n        </div>\n      </div>\n    </Region>\n  );\n}\n",
  "end-card.tsx": "// raea add end-card: the closing card: the brand's name or logo, one line, and the ask (follow, shop, try). Give it the\n// last 2 to 3 seconds in a <Sequence>; it fades in over the footage or a fill of the brand's background.\nimport { AbsoluteFill, Img, interpolate, useCurrentFrame } from \"@raea/motion\";\n\ntype Props = {\n  name: string;\n  /** a logo file under media/ (optional) */\n  logo?: string;\n  line?: string;\n  /** the ask: \"Shop now\", \"Link in bio\" */\n  cta?: string;\n  /** cover the footage with the brand's background (default) or sit on it */\n  fill?: boolean;\n};\n\nexport default function EndCard({ name, logo, line, cta, fill = true }: Props) {\n  const f = useCurrentFrame();\n  const t = interpolate(f, [0, 12], [0, 1], { extrapolateRight: \"clamp\" });\n  return (\n    <AbsoluteFill style={{ opacity: t }} className={`${fill ? \"bg-brand-bg\" : \"\"} flex flex-col items-center justify-center gap-8 px-16 text-center font-brand text-brand-ink`}>\n      {logo ? <Img src={logo} className=\"h-40 object-contain\" /> : <div className=\"text-display font-black\">{name}</div>}\n      {line ? <div className=\"text-title font-bold\">{line}</div> : null}\n      {cta ? <div className=\"rounded-full bg-brand-accent px-12 py-5 text-title font-extrabold text-brand-on-accent\">{cta}</div> : null}\n    </AbsoluteFill>\n  );\n}\n",
  "face-frame.tsx": "// raea add face-frame: a talking take cropped around the face for the edit's shape, the eyes held at a height you pick.\n// The engine reads the face itself (framing=\"face\"); punchIn tightens it (1.15 is a usual punch-in for emphasis).\nimport { Video } from \"@raea/motion\";\n\ntype Props = {\n  src: string;\n  startFrom?: number;\n  endAt?: number;\n  /** 1 = framed to fit; above 1 = tighter */\n  punchIn?: number;\n  volume?: number;\n};\n\nexport default function FaceFrame({ src, startFrom, endAt, punchIn = 1, volume = 1 }: Props) {\n  return <Video src={src} startFrom={startFrom} endAt={endAt} framing=\"face\" punchIn={punchIn} volume={volume} style={{ width: \"100%\", height: \"100%\" }} />;\n}\n",
  "follow.tsx": "// raea add follow: the ask as a pill that hugs its text (\"Follow for part 2\", \"Shop the stack\"). Give it the moment the\n// speaker asks, or the last seconds.\nimport { Region, interpolate, useCurrentFrame } from \"@raea/motion\";\n\ntype Props = { text: string; region?: \"auto\" | \"top\" | \"bottom\" | \"center\" };\n\nexport default function Follow({ text, region = \"top\" }: Props) {\n  const t = interpolate(useCurrentFrame(), [0, 10], [0, 1], { extrapolateRight: \"clamp\" });\n  return (\n    <Region name={region}>\n      <div className=\"flex justify-center\">\n        <div style={{ opacity: t, transform: `scale(${0.85 + 0.15 * t})` }} className=\"rounded-full bg-brand-accent px-12 py-5 font-brand text-title font-extrabold text-brand-on-accent shadow-xl\">{text}</div>\n      </div>\n    </Region>\n  );\n}\n",
  "lockup.tsx": "// raea add lockup: a few lines stacked big, each landing as it's said. \" / \" splits the lines; *word* marks the accent.\n// Put it in a <Sequence> over the words it echoes; each line appears on its first word (or one by one, 8 frames apart,\n// when the line isn't said). Styled only from the brand's tokens.\nimport { Easing, Region, findPhrase, interpolate, useCurrentFrame, useWords } from \"@raea/motion\";\n\ntype Props = { text: string; region?: \"auto\" | \"top\" | \"bottom\" | \"center\"; small?: boolean };\n\nexport default function Lockup({ text, region = \"top\", small = false }: Props) {\n  const f = useCurrentFrame();\n  const words = useWords();\n  const lines = text.split(\" / \");\n  const at = (line: string, i: number) => {\n    try {\n      return findPhrase(words, line.replace(/\\*/g, \"\").split(/\\s+/).slice(0, 2).join(\" \"));\n    } catch {\n      return i * 8;\n    }\n  };\n  return (\n    <Region name={region}>\n      <div className={`flex flex-col items-center gap-2 text-center font-brand font-black uppercase leading-none text-brand-ink [text-shadow:0_4px_24px_rgba(0,0,0,0.5)] ${small ? \"text-title\" : \"text-display\"}`}>\n        {lines.map((line, i) => {\n          const t = interpolate(f - at(line, i), [0, 8], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\", easing: Easing.bezier(0.05, 0.7, 0.1, 1) });\n          return (\n            <div key={i} style={{ opacity: t, transform: `translateY(${(1 - t) * 30}px) scale(${0.92 + 0.08 * t})` }}>\n              {line.split(/(\\*[^*]+\\*)/).map((part, k) => (part.startsWith(\"*\") ? <span key={k} className=\"text-brand-accent\">{part.slice(1, -1)}</span> : <span key={k}>{part}</span>))}\n            </div>\n          );\n        })}\n      </div>\n    </Region>\n  );\n}\n",
  "notthat.tsx": "// raea add notthat: a lead statement, then the idea it rejects on a card, struck through when the speaker says\n// strikeSay (\"not X, but Y\"). strikeSay is a phrase from the transcript, word for word.\nimport { Easing, Region, findPhrase, interpolate, useCurrentFrame, useWords } from \"@raea/motion\";\n\ntype Props = { lead: string; not: string; strikeSay?: string; region?: \"auto\" | \"top\" | \"bottom\" | \"center\" };\n\n// \" / \" splits lines and *word* marks the accent, as in a lockup\nconst lines = (t: string) =>\n  t.split(\" / \").map((line, i) => (\n    <div key={i}>{line.split(/(\\*[^*]+\\*)/).map((p, k) => (p.startsWith(\"*\") ? <span key={k} className=\"text-brand-accent\">{p.slice(1, -1)}</span> : <span key={k}>{p}</span>))}</div>\n  ));\n\nexport default function NotThat({ lead, not, strikeSay, region = \"top\" }: Props) {\n  const f = useCurrentFrame();\n  const words = useWords();\n  let at = 24;\n  if (strikeSay) {\n    try { at = findPhrase(words, strikeSay); } catch { at = 24; }\n  }\n  const ease = (from: number, len = 10) => interpolate(f - from, [0, len], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\", easing: Easing.bezier(0.05, 0.7, 0.1, 1) });\n  const card = ease(6);\n  const strike = ease(at, 8);\n  return (\n    <Region name={region}>\n      <div className=\"flex flex-col items-center gap-6 text-center font-brand\">\n        <div style={{ opacity: ease(0) }} className=\"rounded-brand bg-brand-surface px-8 py-4 text-title font-extrabold text-brand-on-surface\">{lines(lead)}</div>\n        <div style={{ opacity: card, transform: `scale(${0.9 + 0.1 * card})` }} className=\"relative rounded-brand bg-brand-surface px-10 py-6 text-title font-extrabold text-brand-on-surface shadow-xl\">\n          <span style={{ opacity: 1 - 0.45 * strike }}>{lines(not)}</span>\n          <div className=\"absolute left-6 right-6 top-1/2 h-2 rounded-full bg-brand-accent\" style={{ transform: `scaleX(${strike})`, transformOrigin: \"left\" }} />\n        </div>\n      </div>\n    </Region>\n  );\n}\n",
  "screen-fit.tsx": "// raea add screen-fit: a landscape screen recording shown whole in a vertical frame, over a soft fill of itself, instead\n// of a cover crop that cuts its sides off (every app render on 2026-10-16 lost Jetflow's UI that way). `raea frame`\n// says when a take wants this. Leaves the space above and below for a headline and captions.\nimport { AbsoluteFill, Video, useVideoConfig } from \"@raea/motion\";\n\ntype Props = {\n  src: string;\n  /** source frames, as <Video> takes them */\n  startFrom?: number;\n  endAt?: number;\n  /** the recording's own aspect (width / height); 16/9 when not given */\n  aspect?: number;\n  /** where its centre sits, as a share of the frame's height (0.5 = the middle) */\n  y?: number;\n};\n\nexport default function ScreenFit({ src, startFrom, endAt, aspect = 16 / 9, y = 0.5 }: Props) {\n  const { width, height } = useVideoConfig();\n  const h = width / aspect;\n  const top = Math.max(0, Math.min(height - h, height * y - h / 2));\n  return (\n    <AbsoluteFill className=\"bg-brand-bg\">\n      <Video src={src} startFrom={startFrom} endAt={endAt} muted style={{ position: \"absolute\", inset: 0, width: \"100%\", height: \"100%\", objectFit: \"cover\", opacity: 0.35, filter: \"blur(40px)\" }} />\n      <Video src={src} startFrom={startFrom} endAt={endAt} style={{ position: \"absolute\", left: 0, top, width, height: h, objectFit: \"contain\" }} className=\"rounded-brand shadow-2xl\" />\n    </AbsoluteFill>\n  );\n}\n",
  "statcard.tsx": "// raea add statcard: a number and up to three lines beside it (*word* marks the accent), and up to two labelled bars\n// that fill on the words that say them. Use it only when the footage says a real number; every claim comes from the\n// brand's own material or the take. *_say props are phrases from the transcript, word for word.\nimport { Easing, Region, findPhrase, interpolate, useCurrentFrame, useWords } from \"@raea/motion\";\n\ntype Bar = { label: string; value: number; say?: string };\ntype Props = { big: string; bigSay?: string; l1?: string; l2?: string; l3?: string; bars?: Bar[]; region?: \"auto\" | \"top\" | \"bottom\" | \"center\" };\n\nconst accent = (s: string) => s.split(/(\\*[^*]+\\*)/).map((p, k) => (p.startsWith(\"*\") ? <span key={k} className=\"text-brand-accent\">{p.slice(1, -1)}</span> : <span key={k}>{p}</span>));\n\nexport default function StatCard({ big, bigSay, l1, l2, l3, bars = [], region = \"top\" }: Props) {\n  const f = useCurrentFrame();\n  const words = useWords();\n  const when = (say: string | undefined, d: number) => {\n    if (!say) return d;\n    try { return findPhrase(words, say); } catch { return d; }\n  };\n  const ease = (from: number, len = 10) => interpolate(f - from, [0, len], [0, 1], { extrapolateLeft: \"clamp\", extrapolateRight: \"clamp\", easing: Easing.bezier(0.05, 0.7, 0.1, 1) });\n  const t = ease(when(bigSay, 0));\n  return (\n    <Region name={region}>\n      <div style={{ opacity: t, transform: `translateY(${(1 - t) * 40}px)` }} className=\"mx-auto w-[86%] rounded-brand bg-brand-surface p-10 font-brand text-brand-on-surface shadow-xl\">\n        <div className=\"flex items-center gap-8\">\n          <div className=\"text-display font-black leading-none text-brand-accent\">{big}</div>\n          <div className=\"flex flex-col text-body font-bold leading-snug\">\n            {l1 ? <div>{accent(l1)}</div> : null}\n            {l2 ? <div>{accent(l2)}</div> : null}\n            {l3 ? <div>{accent(l3)}</div> : null}\n          </div>\n        </div>\n        {bars.map((b, i) => {\n          const fill = ease(when(b.say, 12 + i * 10), 18);\n          return (\n            <div key={i} className=\"mt-6\">\n              <div className=\"mb-2 flex justify-between text-label font-bold uppercase\"><span>{b.label}</span><span>{Math.round(b.value * fill)}%</span></div>\n              <div className=\"h-5 w-full rounded-full bg-brand-3\"><div className=\"h-5 rounded-full bg-brand-accent\" style={{ width: `${b.value * fill}%` }} /></div>\n            </div>\n          );\n        })}\n      </div>\n    </Region>\n  );\n}\n"
};
